"use strict";const e=require("../http/client.js"),s=require("../constants/customer.js"),t=require("../../utils/api-response.js");function r(e){const s=t.unwrapResponseBody(e.data),r=200===e.statusCode&&t.isApiSuccess(s);return{ok:r,data:s.data,msg:s.msg||(r?"操作成功":"操作失败")}}exports.createTicket=function(t){return new Promise((o=>{e.request({service:"customer",path:s.CUSTOMER_API.TICKET,method:"POST",data:t,success:e=>o(r(e)),fail:e=>o({ok:!1,data:null,msg:e.errMsg||"网络错误"})})}))},exports.fetchMyTickets=function(r={}){return new Promise((o=>{e.request({service:"customer",path:s.CUSTOMER_API.TICKET_MY,method:"GET",data:r,success:e=>o(function(e){const s=t.unwrapResponseBody(e.data),r=200===e.statusCode&&t.isApiSuccess(s);return{ok:r,rows:t.pickApiList(s),total:s.total??0,msg:s.msg||(r?"查询成功":"加载失败")}}(e)),fail:e=>o({ok:!1,rows:[],total:0,msg:e.errMsg||"网络错误"})})}))},exports.fetchTicketDetail=function(t){return new Promise((o=>{e.request({service:"customer",path:`${s.CUSTOMER_API.TICKET}/${t}`,method:"GET",success:e=>o(r(e)),fail:e=>o({ok:!1,data:null,msg:e.errMsg||"网络错误"})})}))},exports.fetchTicketUnreadCount=function(){return new Promise((t=>{e.request({service:"customer",path:s.CUSTOMER_API.TICKET_UNREAD_COUNT,method:"GET",success:e=>{const s=r(e);t({ok:s.ok,count:Number(s.data)||0,msg:s.msg})},fail:e=>t({ok:!1,count:0,msg:e.errMsg||"网络错误"})})}))},exports.replyTicket=function(t,o){return new Promise((c=>{e.request({service:"customer",path:`${s.CUSTOMER_API.TICKET}/${t}/message`,method:"POST",data:{content:o},success:e=>c(r(e)),fail:e=>c({ok:!1,data:null,msg:e.errMsg||"网络错误"})})}))};
